<?php
use StarZarei\UniversalPOS\POS\App;
use StarZarei\UniversalPOS\POS\Strings;

defined( 'ABSPATH' ) || exit;
$management_receipt = $management_receipt ?? false;
$rtl = 'fa_IR' === Strings::locale();
$t = static fn( $text ) => esc_html( Strings::t( $text ) );
$price = static fn( $value ) => esc_html( "\u{2066}" . html_entity_decode( wp_strip_all_tags( wc_price( $value, array( 'currency' => $order->get_currency(), 'decimals' => $sale['price_decimals'] ) ) ), ENT_QUOTES, 'UTF-8' ) . "\u{2069}" );
$status = array( 'processing' => Strings::t( 'Processing' ), 'completed' => Strings::t( 'Completed' ), 'refunded' => Strings::t( 'Refunded' ), 'cancelled' => Strings::t( 'Cancelled' ) )[ $order->get_status() ] ?? wc_get_order_status_name( $order->get_status() );
$cashier = get_userdata( (int) $order->get_meta( '_upos_cashier_id', true ) );
$address = array_filter( array( get_option( 'woocommerce_store_address', '' ), get_option( 'woocommerce_store_address_2', '' ), get_option( 'woocommerce_store_city', '' ), get_option( 'woocommerce_store_postcode', '' ) ) );
?>
<!doctype html>
<html lang="<?php echo $rtl ? 'fa' : 'en'; ?>" dir="<?php echo $rtl ? 'rtl' : 'ltr'; ?>">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?php echo $t( 'Receipt' ) . ' ' . esc_html( $order->get_order_number() ); ?></title><link rel="stylesheet" href="<?php echo esc_url( App::asset( 'css/receipt.css' ) ); ?>"><script defer src="<?php echo esc_url( App::asset( 'js/receipt.js' ) ); ?>"></script></head>
<body class="paper-<?php echo (int) $paper; ?>">
<nav class="print-toolbar" aria-label="<?php echo esc_attr( Strings::t( 'Print controls' ) ); ?>"><form method="get"><?php if ( $management_receipt ) : ?><input type="hidden" name="action" value="upos_order_receipt"><input type="hidden" name="order_id" value="<?php echo (int) $order->get_id(); ?>"><?php wp_nonce_field( 'upos_order_receipt', '_wpnonce', false ); ?><?php else : ?><input type="hidden" name="upos_receipt" value="<?php echo (int) $order->get_id(); ?>"><?php endif; ?><label><?php echo $t( 'Receipt width' ); ?><select name="paper"><option value="80" <?php selected( $paper, 80 ); ?>>80 mm</option><option value="58" <?php selected( $paper, 58 ); ?>>58 mm</option></select></label><button type="submit"><?php echo $t( 'Apply' ); ?></button></form><button type="button" id="print"><?php echo $t( 'Print receipt' ); ?></button><a href="<?php echo esc_url( App::url() ); ?>"><?php echo $t( 'Back to point of sale' ); ?></a></nav>
<main class="receipt">
	<header><h1><?php echo esc_html( get_bloginfo( 'name' ) ); ?></h1><?php if ( $address ) : ?><p><?php echo esc_html( implode( '، ', $address ) ); ?></p><?php endif; ?><h2><?php echo $t( 'Sales receipt' ); ?></h2></header>
	<dl class="receipt-meta"><div><dt><?php echo $t( 'Order number' ); ?></dt><dd><?php echo esc_html( $order->get_order_number() ); ?></dd></div><div><dt><?php echo $t( 'Payment date' ); ?></dt><dd dir="ltr"><?php echo esc_html( $order->get_date_paid()->date_i18n( 'Y/m/d H:i' ) ); ?></dd></div><div><dt><?php echo $t( 'Status' ); ?></dt><dd><?php echo esc_html( $status ); ?></dd></div><div><dt><?php echo $t( 'Customer' ); ?></dt><dd><?php echo esc_html( $order->get_formatted_billing_full_name() ); ?></dd></div><?php if ( $order->get_billing_phone() ) : ?><div><dt><?php echo $t( 'Mobile number' ); ?></dt><dd dir="ltr"><?php echo esc_html( $order->get_billing_phone() ); ?></dd></div><?php endif; ?><div><dt><?php echo $t( 'Cashier' ); ?></dt><dd><?php echo $cashier ? esc_html( $cashier->display_name ) : $t( $management_receipt && 'online' === $sale['channel'] ? 'Online' : 'Deleted user' ); ?></dd></div></dl>
	<table><caption class="sr-only"><?php echo $t( 'Purchased items' ); ?></caption><thead><tr><th scope="col"><?php echo $t( 'Product' ); ?></th><th scope="col"><?php echo $t( 'Qty' ); ?></th><th scope="col"><?php echo $t( 'Total' ); ?></th></tr></thead><tbody><?php foreach ( $order->get_items( array( 'line_item', 'fee', 'shipping' ) ) as $item ) : ?><tr><td><?php echo esc_html( $item->get_name() ); ?><?php if ( $item instanceof \WC_Order_Item_Product ) : ?><small><?php echo $t( 'Unit price' ) . ': ' . $price( $order->get_item_subtotal( $item, false, false ) ); ?></small><?php endif; ?></td><td><?php echo esc_html( $item->get_quantity() ); ?></td><td><?php echo $price( $item->get_total() ); ?></td></tr><?php endforeach; ?></tbody></table>
	<dl class="receipt-totals"><div><dt><?php echo $t( 'Subtotal' ); ?></dt><dd><?php echo $price( $order->get_subtotal() ); ?></dd></div><?php if ( (float) $order->get_discount_total() ) : ?><div><dt><?php echo $t( $sale['manual_discount'] ? 'Manual discount' : 'Discount' ); ?></dt><dd><?php echo $price( $order->get_discount_total() ); ?></dd></div><?php endif; ?><div><dt><?php echo $t( 'Tax' ); ?></dt><dd><?php echo $price( $order->get_total_tax() ); ?></dd></div><div class="grand"><dt><?php echo $t( 'Total received' ); ?></dt><dd><?php echo $price( $order->get_total() ); ?></dd></div><?php if ( $order->get_total_refunded() > 0 ) : ?><div><dt><?php echo $t( 'Refunded amount' ); ?></dt><dd><?php echo $price( $order->get_total_refunded() ); ?></dd></div><div><dt><?php echo $t( 'Total after refunds' ); ?></dt><dd><?php echo $price( $order->get_total() - $order->get_total_refunded() ); ?></dd></div><?php endif; ?></dl>
	<?php if ( $sale['coupon'] ) : ?><p><?php echo $t( 'Coupon code' ) . ': ' . esc_html( $sale['coupon'] ); ?></p><?php endif; ?>
	<section class="receipt-payments"><h2><?php echo $t( 'Payment details' ); ?></h2><?php if ( ! $sale['payments'] ) : ?><p><?php echo $management_receipt && (float) $order->get_total() > 0 ? esc_html( $order->get_payment_method_title() ) : $t( 'No payment required' ); ?></p><?php endif; ?><?php foreach ( $sale['payments'] as $line ) : ?><div><strong><?php echo esc_html( Strings::t( array( 'cash' => 'Cash', 'card_terminal' => 'Card terminal (manually confirmed)', 'bank_transfer' => 'Bank transfer (manually confirmed)' )[ $line['method'] ] ?? $line['method'] ) ); ?></strong><span><?php echo $price( $line['amount'] ); ?></span></div><?php if ( $line['reference'] ) : ?><p class="reference"><?php echo $t( 'Tracking reference' ) . ': ' . esc_html( $line['reference'] ); ?></p><?php endif; ?><?php endforeach; ?></section>
	<footer><p><?php echo $t( 'Thank you for your purchase.' ); ?></p><p><?php echo $t( $management_receipt ? 'WooCommerce order receipt. Refunds are shown separately.' : 'This is a record of manually confirmed funds, not a bank transaction slip.' ); ?></p></footer>
</main>
</body></html>
